package media

import (
	"bytes"
	"embed"
	"errors"
	"fmt"
	"io"
	"sync"
	"time"

	"github.com/pion/webrtc/v3"
	"github.com/pion/webrtc/v3/pkg/media/ivfreader"
	"github.com/pion/webrtc/v3/pkg/media/oggreader"
)

// Media kinds.
const (
	KindAudio = "audio"
	KindVideo = "video"
)

// Content files, generated by scripts/gen-media.sh.
//
//go:embed assets/video.ivf assets/audio.ogg assets/video_90.ivf assets/video_180.ivf assets/video_720.ivf
//go:embed assets/vp9_*.ivf assets/av1_*.ivf assets/h264_*.h264
var assets embed.FS

const (
	videoClockRate = 90000
	opusClockRate  = 48000
	opusFrame      = 20 * time.Millisecond
)

// OpusFrame is the duration of the audio packets the bots send.
const OpusFrame = opusFrame

// Frame is one encoded frame (video) or packet (audio) of the content.
type Frame struct {
	Data     []byte
	Duration time.Duration // Time until the next frame
	Samples  uint32        // Duration in RTP clock ticks (timestamp increment to the next frame)
	// Layers are the layer frames of a scalable picture, lowest spatial
	// layer first; Data is then the lowest one's. Nil for other content.
	Layers []LayerFrame
}

// LayerFrame is one spatial layer's frame of a scalable picture.
type LayerFrame struct {
	Data                  []byte
	SpatialID, TemporalID int
}

// Content is pre-encoded media that bots loop. It is read-only and shared.
type Content struct {
	Kind         string
	Codec        webrtc.RTPCodecCapability
	Frames       []Frame
	LoopDuration time.Duration
	// Width and Height are the video's size from its IVF header (0 for
	// audio).
	Width, Height int
	// VideoCodec is the video's codec (empty for audio).
	VideoCodec VideoCodec
	// Heights are the heights of the video's layers, low to high: one for
	// a single stream or a simulcast layer, three for scalable content.
	Heights []int
}

var (
	loadOnce sync.Once
	loaded   map[string]*Content
	loadErr  error
)

// LoadContent returns the built-in content for kind ("audio" or "video").
// The files are parsed once per process.
func LoadContent(kind string) (*Content, error) {
	loadOnce.Do(func() {
		loaded = map[string]*Content{}
		var c *Content
		if c, loadErr = loadVideoFile(CodecVP8, "video.ivf", 360); loadErr != nil {
			return
		}
		loaded[KindVideo] = c
		if c, loadErr = loadAudio(); loadErr != nil {
			return
		}
		loaded[KindAudio] = c
	})
	if loadErr != nil {
		return nil, loadErr
	}
	c, ok := loaded[kind]
	if !ok {
		return nil, fmt.Errorf("no media content for kind %q", kind)
	}
	return c, nil
}

// Layer heights sent for each highest height (FR-010), low to high.
var layerSets = map[int][]int{360: {90, 180, 360}, 720: {180, 360, 720}}

// LoadLayers returns the three VP8 simulcast layers, low to high, whose
// highest is maxHeight lines (360 or 720). Every layer has the same frames
// timing and keyframes at the same frames, so they can be sent in lockstep.
func LoadLayers(maxHeight int) ([]*Content, error) {
	return LoadVideo(CodecVP8, ArrangementSimulcast, maxHeight)
}

var (
	videoFilesMu sync.Mutex
	loadedFiles  = map[string]*Content{} // By file name
)

// LoadVideo returns the built-in video a run sends in codec c: one Content
// for a single stream (360 lines; maxHeight is ignored), one per layer, low
// to high, for simulcast, and one holding every layer for scalable (SVC)
// content. maxHeight is 360 or 720 for the layered arrangements. Files are
// parsed once per process and shared.
func LoadVideo(c VideoCodec, arr Arrangement, maxHeight int) ([]*Content, error) {
	if _, err := ParseVideoCodec(string(c)); err != nil {
		return nil, err
	}
	m, err := loadManifest()
	if err != nil {
		return nil, err
	}
	switch arr {
	case ArrangementSingle:
		if c == CodecVP8 {
			v, err := LoadContent(KindVideo)
			if err != nil {
				return nil, err
			}
			return []*Content{v}, nil
		}
		v, err := loadEntry(m, c, arr, defaultHeight, 0)
		if err != nil {
			return nil, err
		}
		return []*Content{v}, nil
	case ArrangementSimulcast:
		heights, ok := layerSets[maxHeight]
		if !ok {
			return nil, fmt.Errorf("no simulcast layers up to %d lines (360 or 720)", maxHeight)
		}
		out := make([]*Content, 0, len(heights))
		for _, h := range heights {
			var v *Content
			if c == CodecVP8 && h == defaultHeight {
				v, err = LoadContent(KindVideo)
			} else {
				v, err = loadEntry(m, c, arr, h, 0)
			}
			if err != nil {
				return nil, fmt.Errorf("%d-line layer: %w", h, err)
			}
			out = append(out, v)
		}
		if err := checkAligned(out); err != nil {
			return nil, err
		}
		return out, nil
	case ArrangementSVC:
		if c != CodecVP9 && c != CodecAV1 {
			return nil, fmt.Errorf("no %s svc content: scalable layers are VP9 and AV1 only", c)
		}
		if _, ok := layerSets[maxHeight]; !ok {
			return nil, fmt.Errorf("no svc layers up to %d lines (360 or 720)", maxHeight)
		}
		e, err := m.lookup(c, arr, maxHeight, maxHeight)
		if err != nil {
			return nil, err
		}
		v, err := loadSVCFile(c, e.File, layerSets[maxHeight])
		if err != nil {
			return nil, err
		}
		return []*Content{v}, nil
	}
	return nil, fmt.Errorf("unknown video arrangement %q", arr)
}

// loadEntry loads the file content.json gives for one codec and height.
func loadEntry(m manifest, c VideoCodec, arr Arrangement, height, maxHeight int) (*Content, error) {
	e, err := m.lookup(c, arr, height, maxHeight)
	if err != nil {
		return nil, err
	}
	return loadVideoFile(c, e.File, height)
}

// LayerHeights returns the heights of the simulcast layers whose highest is
// maxHeight lines (360 or 720), low to high.
func LayerHeights(maxHeight int) ([]int, error) {
	heights, ok := layerSets[maxHeight]
	if !ok {
		return nil, fmt.Errorf("no simulcast layers up to %d lines (360 or 720)", maxHeight)
	}
	return append([]int(nil), heights...), nil
}

// checkAligned reports an error unless the layers have the same frame
// timing and keyframes at the same frames.
func checkAligned(out []*Content) error {
	for _, c := range out[1:] {
		if len(c.Frames) != len(out[0].Frames) || c.LoopDuration != out[0].LoopDuration {
			return fmt.Errorf("simulcast layers differ in length")
		}
		for i, f := range c.Frames {
			if f.Samples != out[0].Frames[i].Samples || isKeyframe(c.VideoCodec, f.Data) != isKeyframe(out[0].VideoCodec, out[0].Frames[i].Data) {
				return fmt.Errorf("simulcast layers not aligned at frame %d", i)
			}
		}
	}
	return nil
}

// loadVideoFile parses an embedded video file once.
func loadVideoFile(c VideoCodec, name string, height int) (*Content, error) {
	videoFilesMu.Lock()
	defer videoFilesMu.Unlock()
	if v := loadedFiles[name]; v != nil {
		return v, nil
	}
	data, err := assets.ReadFile("assets/" + name)
	if err != nil {
		return nil, err
	}
	var v *Content
	switch c {
	case CodecVP8, CodecVP9, CodecAV1:
		v, err = parseIVFAs(c, data)
	case CodecH264:
		v, err = parseH264(data, height)
	default:
		err = fmt.Errorf("no loader for %s content", c)
	}
	if err != nil {
		return nil, fmt.Errorf("%s: %w", name, err)
	}
	if v.Heights == nil {
		v.Heights = []int{height}
	}
	loadedFiles[name] = v
	return v, nil
}

// parseIVF reads VP8 content from an IVF file whose frames are all shown
// (no alt-ref frames), so they can be paced by their timestamps.
func parseIVF(data []byte) (*Content, error) {
	return parseIVFAs(CodecVP8, data)
}

var ivfFourCC = map[VideoCodec]string{CodecVP8: "VP80", CodecVP9: "VP90", CodecAV1: "AV01"}

// capability returns the Pion codec capability the bots send codec c as.
func capability(c VideoCodec) webrtc.RTPCodecCapability {
	return webrtc.RTPCodecCapability{MimeType: c.MimeType(), ClockRate: videoClockRate, SDPFmtpLine: c.FmtpLine()}
}

// parseIVFAs reads VP8, VP9 or AV1 content from an IVF file whose frames
// are all shown, one per timestamp. AV1 frames are kept as their OBUs
// without the temporal delimiter.
func parseIVFAs(codec VideoCodec, data []byte) (*Content, error) {
	c, frames, tb, err := readIVF(codec, data)
	if err != nil {
		return nil, err
	}
	for _, f := range frames {
		c.Frames = append(c.Frames, Frame{Data: f.data})
	}
	if err := setTiming(c, frames, tb); err != nil {
		return nil, err
	}
	return c, nil
}

// ivfFrame is one IVF frame: its data (AV1: without the temporal
// delimiter) and its timestamp in timebase units.
type ivfFrame struct {
	data []byte
	ts   uint64
}

// ivfTimebase is the IVF header's timebase, numerator over denominator
// seconds.
type ivfTimebase struct{ num, den uint64 }

// readIVF reads an IVF file's header and frames.
func readIVF(codec VideoCodec, data []byte) (*Content, []ivfFrame, ivfTimebase, error) {
	var tb ivfTimebase
	r, header, err := ivfreader.NewWith(bytes.NewReader(data))
	if err != nil {
		return nil, nil, tb, fmt.Errorf("video content: %w", err)
	}
	if header.FourCC != ivfFourCC[codec] {
		return nil, nil, tb, fmt.Errorf("video content: expected %s, got %q", codec, header.FourCC)
	}
	c := &Content{
		Kind:       KindVideo,
		Codec:      capability(codec),
		Width:      int(header.Width),
		Height:     int(header.Height),
		VideoCodec: codec,
	}
	tb = ivfTimebase{uint64(header.TimebaseNumerator), uint64(header.TimebaseDenominator)}
	var frames []ivfFrame
	for {
		frame, fh, err := r.ParseNextFrame()
		if errors.Is(err, io.EOF) {
			break
		}
		if err != nil {
			return nil, nil, tb, fmt.Errorf("video content: %w", err)
		}
		if codec == CodecAV1 {
			if frame, err = av1ContentFrame(frame); err != nil {
				return nil, nil, tb, fmt.Errorf("video content: frame %d: %w", len(frames), err)
			}
		}
		frames = append(frames, ivfFrame{data: frame, ts: fh.Timestamp})
	}
	return c, frames, tb, nil
}

// setTiming sets each of c's frames' duration from the timestamps of the
// pictures (one per frame): until the next one, the last one as long as
// the previous one.
func setTiming(c *Content, pictures []ivfFrame, tb ivfTimebase) error {
	if len(c.Frames) < 2 {
		return fmt.Errorf("video content: too few frames")
	}
	// IVF timestamps count timebase units of numerator/denominator seconds;
	// convert exactly, without rounding the unit first.
	toDuration := func(units uint64) time.Duration { return time.Duration(units * tb.num * uint64(time.Second) / tb.den) }
	toTicks := func(units uint64) uint32 { return uint32(units * tb.num * videoClockRate / tb.den) }
	units := make([]uint64, len(c.Frames))
	for i := range c.Frames {
		if i+1 < len(c.Frames) {
			units[i] = pictures[i+1].ts - pictures[i].ts
		} else {
			units[i] = units[i-1]
		}
		c.Frames[i].Duration = toDuration(units[i])
		c.Frames[i].Samples = toTicks(units[i])
		c.LoopDuration += c.Frames[i].Duration
	}
	return nil
}

// loadSVCFile parses an embedded scalable file once.
func loadSVCFile(c VideoCodec, name string, heights []int) (*Content, error) {
	videoFilesMu.Lock()
	defer videoFilesMu.Unlock()
	if v := loadedFiles[name]; v != nil {
		return v, nil
	}
	data, err := assets.ReadFile("assets/" + name)
	if err != nil {
		return nil, err
	}
	v, err := parseSVC(c, data, heights)
	if err != nil {
		return nil, fmt.Errorf("%s: %w", name, err)
	}
	loadedFiles[name] = v
	return v, nil
}

// vp9TemporalIDs is the temporal layer of picture i, vp9TemporalIDs[i%4],
// in the encoder's 0-2-1-2 pattern (VP9 frames carry no temporal ID).
var vp9TemporalIDs = [4]int{0, 2, 1, 2}

// parseSVC reads scalable content (scripts/gen-media.sh svc): VP9 has one
// superframe per picture holding its layer frames; AV1 has one IVF frame
// per layer frame, the picture's frames sharing a timestamp, each with an
// OBU extension header giving its layers.
func parseSVC(codec VideoCodec, data []byte, heights []int) (*Content, error) {
	c, frames, tb, err := readIVF(codec, data)
	if err != nil {
		return nil, err
	}
	c.Heights = append([]int(nil), heights...)
	var pictures []ivfFrame
	switch codec {
	case CodecVP9:
		for i, f := range frames {
			parts, err := splitVP9Superframe(f.data)
			if err != nil {
				return nil, fmt.Errorf("video content: picture %d: %w", i, err)
			}
			var layers []LayerFrame
			for s, d := range parts {
				layers = append(layers, LayerFrame{Data: d, SpatialID: s, TemporalID: vp9TemporalIDs[i%4]})
			}
			c.Frames = append(c.Frames, Frame{Layers: layers})
			pictures = append(pictures, f)
		}
	case CodecAV1:
		for _, f := range frames {
			sid, tid, err := av1FrameLayers(f.data)
			if err != nil {
				return nil, fmt.Errorf("video content: picture %d: %w", len(c.Frames), err)
			}
			if len(pictures) == 0 || pictures[len(pictures)-1].ts != f.ts {
				c.Frames = append(c.Frames, Frame{})
				pictures = append(pictures, f)
			}
			p := &c.Frames[len(c.Frames)-1]
			p.Layers = append(p.Layers, LayerFrame{Data: f.data, SpatialID: sid, TemporalID: tid})
		}
	default:
		return nil, fmt.Errorf("no %s svc content: scalable layers are VP9 and AV1 only", codec)
	}
	for i := range c.Frames {
		p := &c.Frames[i]
		if len(p.Layers) != len(heights) {
			return nil, fmt.Errorf("video content: picture %d has %d layer frames, want %d", i, len(p.Layers), len(heights))
		}
		for s, l := range p.Layers {
			if l.SpatialID != s {
				return nil, fmt.Errorf("video content: picture %d: layer frame %d of spatial layer %d", i, s, l.SpatialID)
			}
		}
		p.Data = p.Layers[0].Data
	}
	if err := setTiming(c, pictures, tb); err != nil {
		return nil, err
	}
	return c, nil
}

// splitVP9Superframe returns the frames of a VP9 superframe (VP9 bitstream
// specification, annex B): an index at the end, a marker byte 0b110xxyyy
// (xx bytes per size - 1, yyy frames - 1), the sizes little endian, and the
// marker again. A frame without an index is returned alone.
func splitVP9Superframe(b []byte) ([][]byte, error) {
	if len(b) == 0 {
		return nil, fmt.Errorf("empty VP9 frame")
	}
	m := b[len(b)-1]
	if m&0xe0 != 0xc0 {
		return [][]byte{b}, nil
	}
	bytesPer, n := int(m>>3&3)+1, int(m&7)+1
	ix := 2 + bytesPer*n
	if len(b) < ix || b[len(b)-ix] != m {
		return [][]byte{b}, nil
	}
	sizes := b[len(b)-ix+1 : len(b)-1]
	data := b[:len(b)-ix]
	out := make([][]byte, 0, n)
	for i := 0; i < n; i++ {
		size := 0
		for k := bytesPer - 1; k >= 0; k-- {
			size = size<<8 | int(sizes[i*bytesPer+k])
		}
		if size > len(data) {
			return nil, fmt.Errorf("VP9 superframe: frame %d of %d bytes, %d left", i, size, len(data))
		}
		out = append(out, data[:size])
		data = data[size:]
	}
	return out, nil
}

// h264FrameRate is the H.264 content's frame rate: an Annex B stream has
// no timestamps, and the content is made at 30 fps like the others.
const h264FrameRate = 30

// parseH264 reads H.264 content from an Annex B stream with an access unit
// delimiter before each frame (scripts/gen-media.sh).
func parseH264(data []byte, height int) (*Content, error) {
	aus := h264AccessUnits(data)
	if len(aus) < 2 {
		return nil, fmt.Errorf("video content: too few access units")
	}
	c := &Content{
		Kind:       KindVideo,
		Codec:      capability(CodecH264),
		Width:      height * 16 / 9,
		Height:     height,
		VideoCodec: CodecH264,
	}
	d := time.Second / h264FrameRate
	for _, au := range aus {
		c.Frames = append(c.Frames, Frame{Data: au, Duration: d, Samples: videoClockRate / h264FrameRate})
		c.LoopDuration += d
	}
	return c, nil
}

func loadAudio() (*Content, error) {
	data, err := assets.ReadFile("assets/audio.ogg")
	if err != nil {
		return nil, err
	}
	return parseOgg(data)
}

// parseOgg reads Opus content from an Ogg file holding one 20 ms packet per
// page.
func parseOgg(data []byte) (*Content, error) {
	r, header, err := oggreader.NewWith(bytes.NewReader(data))
	if err != nil {
		return nil, fmt.Errorf("audio content: %w", err)
	}
	if header.Channels == 0 {
		return nil, fmt.Errorf("audio content: invalid Opus header")
	}
	c := &Content{
		Kind:  KindAudio,
		Codec: webrtc.RTPCodecCapability{MimeType: webrtc.MimeTypeOpus, ClockRate: opusClockRate, Channels: 2},
	}
	for {
		page, _, err := r.ParseNextPage()
		if errors.Is(err, io.EOF) {
			break
		}
		if err != nil {
			return nil, fmt.Errorf("audio content: %w", err)
		}
		if bytes.HasPrefix(page, []byte("OpusTags")) || len(page) == 0 {
			continue
		}
		// scripts/gen-media.sh and transcodeFile write one 20 ms packet per
		// page.
		c.Frames = append(c.Frames, Frame{Data: page, Duration: opusFrame, Samples: opusClockRate * uint32(opusFrame/time.Millisecond) / 1000})
		c.LoopDuration += opusFrame
	}
	if len(c.Frames) == 0 {
		return nil, fmt.Errorf("audio content: no packets")
	}
	return c, nil
}

// isKeyframe reports whether a frame of the content is a keyframe.
func isKeyframe(c VideoCodec, frame []byte) bool {
	switch c {
	case CodecVP9:
		return isVP9Keyframe(frame)
	case CodecAV1:
		return isAV1Keyframe(frame)
	case CodecH264:
		return isH264Keyframe(frame)
	default:
		return isVP8Keyframe(frame)
	}
}

// isVP8Keyframe reports whether a VP8 frame is a keyframe (RFC 6386 9.1:
// bit 0 of the frame tag is 0 for keyframes).
func isVP8Keyframe(frame []byte) bool {
	return len(frame) > 0 && frame[0]&0x01 == 0
}
